  [T('Des exemples',`<p>Refuser un logement à quelqu’un à cause de son nom, payer moins une femme pour le même travail, exclure un élève en situation de handicap : ce sont des discriminations.</p><p>Le <b>Défenseur des droits</b> peut aider les victimes.</p>`)],
  [{q:'Un club refuse un enfant parce qu’il porte des lunettes. Est-ce une discrimination ?',s:['Le refus est lié à son apparence.','Cela n’a rien à voir avec ses capacités.','Oui, c’est une <b>discrimination</b>, interdite par la loi.']}],
